# PowerShell completion for demo — generated by `demo completion powershell`
Register-ArgumentCompleter -Native -CommandName demo -ScriptBlock {
  param($wordToComplete, $commandAst, $cursorPosition)
  $valued = @('--data-dir', '--account', '-a', '--site', '-s', '--limit', '-n', '--max', '--param', '-p', '--method', '--url', '--before')
  $before = @($commandAst.CommandElements | Select-Object -Skip 1 |
    Where-Object { $_.Extent.EndOffset -lt $cursorPosition } | ForEach-Object { $_.ToString() })
  $words = @()
  $skip = $false
  foreach ($word in $before) {
    if ($skip) { $skip = $false; continue }
    if ($valued -ccontains $word) { $skip = $true } elseif ($word -notlike '-*') { $words += $word }
  }
  $previous = if ($before.Count -gt 0) { $before[-1] } else { '' }
  if (($valued -ccontains $previous) -and -not (@('--method') -ccontains $previous)) { return }
  $candidates = switch -CaseSensitive -Exact ($previous) {
    '--method' { @('GET', 'POST', 'DELETE') }
    default {
      switch -CaseSensitive -Exact ($words -join ' ') {
        '' { @('session', 'request', 'store', 'completion', 'help', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'session' { @('login', 'list', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'session login' { @('--account', '-a', '--site', '-s', '--force', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'session list' { @('--site', '-s', '--limit', '-n', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'request' { @('get', 'raw', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'req' { @('get', 'raw', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'request get' { @('--account', '-a', '--param', '-p', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'req get' { @('--account', '-a', '--param', '-p', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'request raw' { @('--method', '--url', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'req raw' { @('--method', '--url', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'store' { @('get', 'query', 'prune', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'store get' { @('--data-dir', '--json', '--verbose', '-v', '--help') }
        'store query' { @('--data-dir', '--json', '--verbose', '-v', '--help') }
        'store search' { @('--data-dir', '--json', '--verbose', '-v', '--help') }
        'store prune' { @('--before', '--confirm', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'store purge' { @('--data-dir', '--json', '--verbose', '-v', '--help') }
        'completion' { @('bash', 'zsh', 'fish', 'powershell', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'help' { @('session', 'request', 'store', 'completion', 'help', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'help session' { @('login', 'list', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'help request' { @('get', 'raw', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'help req' { @('get', 'raw', '--data-dir', '--json', '--verbose', '-v', '--help') }
        'help store' { @('get', 'query', 'prune', '--data-dir', '--json', '--verbose', '-v', '--help') }
        default { @('--help') }
      }
    }
  }
  $candidates | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
    [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
  }
}
